const D = { energy:.6, density:.5, speed:1, scale:1, hue:190, x:.5, y:.5, style:'caustic', act:'ripples', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = 6.28318530718, clp=(v,a,b)=>v<a?a:v>b?b:v;
const en=clp(P.energy,0,1), dens=clp(P.density,0,1), spd=clp(P.speed,0.2,4), scl=clp(P.scale,0.4,2.6);
const style=P.style, act=P.act;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

// ---- coarse grid sizing (aspect-fit, ~150 on the long edge) ----
const LS=150;
let GW,GH;
if(width>=height){ GW=LS; GH=Math.max(24,Math.round(LS*height/width)); }
else { GH=LS; GW=Math.max(24,Math.round(LS*width/height)); }
GW=Math.min(176,GW); GH=Math.min(176,GH);
const N=GW*GH;

const hsh=i=>{ const s=Math.sin(i*127.1+(P.seed|0)*311.7)*43758.5453; return s-Math.floor(s); };

// ---- (re)build sim buffers on size/seed change ----
if(!S.u || S.gw!==GW || S.gh!==GH || S.seedUsed!==(P.seed|0)){
  S.gw=GW; S.gh=GH; S.seedUsed=(P.seed|0);
  S.u=new Float32Array(N); S.up=new Float32Array(N);
  // border-absorbing factor: soft damping band near the tank walls (no runaway reflections)
  S.bf=new Float32Array(N);
  const B=Math.max(4,Math.round(Math.min(GW,GH)*0.10));
  for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
    const d=Math.min(x,y,GW-1-x,GH-1-y);
    S.bf[y*GW+x]= d>=B ? 1 : (0.86+0.14*(d/B));
  }
  // seed a few initial drops so the tank starts alive (not a flat field)
  for(let k=0;k<5;k++){
    const cx=Math.floor((0.2+hsh(k*3+1)*0.6)*GW), cy=Math.floor((0.2+hsh(k*3+2)*0.6)*GH), rr=2+Math.floor(hsh(k*3+3)*3);
    const amp=(hsh(k*3+4)<0.5?-1:1)*0.8;
    for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
      const xx=cx+dx, yy=cy+dy; if(xx<0||yy<0||xx>=GW||yy>=GH)continue;
      const dd=dx*dx+dy*dy; if(dd>rr*rr)continue;
      S.u[yy*GW+xx]+=amp*Math.exp(-dd/(rr*rr*0.5));
    }
  }
  S.buf=null;
}
if(!S.buf || S.bkw!==GW || S.bkh!==GH){ if(S.buf&&S.buf.remove)S.buf.remove(); S.buf=createGraphics(GW,GH); S.buf.pixelDensity(1); S.bkw=GW; S.bkh=GH; }

// ---- (re)build wave sources on seed/count change ----
const nSrc = 2 + Math.round(dens*2) + (act==='storm'?1:0);
const nS = Math.min(5, nSrc);
if(!S.src || S.src.length!==nS || S.srcSeed!==(P.seed|0)){
  S.srcSeed=(P.seed|0);
  const src=[];
  for(let i=0;i<nS;i++){
    src.push({
      cx:0.2+hsh(i*9+1)*0.6, cy:0.2+hsh(i*9+2)*0.6,
      orbR:0.03+hsh(i*9+3)*0.09, orb:(hsh(i*9+7)<0.5?-1:1)*(0.15+hsh(i*9+4)*0.4),
      fm:0.7+hsh(i*9+5)*0.8, ph:hsh(i*9+6)*TAU
    });
  }
  S.src=src;
}
const src=S.src;

// ---- color LUT keyed on style + drifting hue ----
const sec=K.section|0;
const hueDrift = sec*11 + Math.sin(K.t*0.02)*8;
const hb = (((P.hue+hueDrift)%360)+360)%360;
const nb = 5 + Math.round(dens*9);
const lkey = style+'|'+Math.round(hb);
if(S.lkey!==lkey){
  S.lkey=lkey;
  const R=new Uint8Array(128),G=new Uint8Array(128),Bc=new Uint8Array(128);
  for(let i=0;i<128;i++){
    const t=i/127; let c;
    if(style==='thermal'){
      const stops=[[8,4,24],[52,10,96],[150,28,120],[224,64,44],[255,152,32],[255,242,186]];
      const ff=t*(stops.length-1); let si=Math.floor(ff); if(si>stops.length-2)si=stops.length-2; const tt=ff-si;
      const a=stops[si],b=stops[si+1];
      R[i]=a[0]+(b[0]-a[0])*tt; G[i]=a[1]+(b[1]-a[1])*tt; Bc[i]=a[2]+(b[2]-a[2])*tt; continue;
    } else if(style==='phosphor'){
      c=color(140,90,4+t*11);
    } else if(style==='blueprint'){
      c=color(212,74,10+t*20);
    } else if(style==='mercury'){
      c=color(210,6+(1-t)*7, 15+t*44+34*Math.pow(t,6));
    } else { // caustic
      c=color((hb+(t-0.5)*26+360)%360, 96-t*54, 6+t*72);
    }
    R[i]=c.levels[0]; G[i]=c.levels[1]; Bc[i]=c.levels[2];
  }
  S.R=R; S.G=G; S.Bc=Bc;
}
const R=S.R,G=S.G,Bc=S.Bc;

// ---- per-frame source positions (K.t orbit + slow per-section migration) ----
const SX=new Float32Array(nS), SY=new Float32Array(nS), SV=new Float32Array(nS);
const gbx=(P.x-0.5)*0.5, gby=(P.y-0.5)*0.5;
let converge=0;
if(act==='tide'){ converge=0.5+0.5*Math.sin(K.t*0.03*spd); }
for(let i=0;i<nS;i++){
  const s=src[i];
  const tgx=0.16+hsh(sec*13+i*29+3)*0.68, tgy=0.16+hsh(sec*13+i*29+5)*0.68;
  s.cx+=(tgx-s.cx)*0.012; s.cy+=(tgy-s.cy)*0.012;
  const a=s.ph+K.t*spd*s.orb;
  const orbR=s.orbR*(0.7+0.4*Math.sin(K.t*0.05*spd+i));
  let pxs=s.cx+Math.cos(a)*orbR+gbx;
  let pys=s.cy+Math.sin(a)*orbR+gby;
  if(act==='tide'){ pxs=0.5+(pxs-0.5)*(1.15-converge*0.7); pys=0.5+(pys-0.5)*(1.15-converge*0.7); }
  SX[i]=clp(pxs,0.05,0.95); SY[i]=clp(pys,0.05,0.95);
  const om=(0.9+s.fm*0.8)*spd*(2.0/scl);
  const amp=(0.5+en*0.25)*(0.75+0.5*K.intensity);
  SV[i]=amp*Math.sin(om*K.t + s.ph*3 + i*1.7);
}

// ---- run the wave equation: leapfrog u'' = c^2 * laplacian(u), damped ----
const c2=0.28, damp=(act==='storm')?0.997:0.9955;
const subs=spd>2.2?2:1;
let cu=S.u, pu=S.up; const bf=S.bf;
for(let it=0;it<subs;it++){
  for(let y=0;y<GH;y++){
    const row=y*GW, rowU=(y>0?y-1:y)*GW, rowD=(y<GH-1?y+1:y)*GW;
    for(let x=0;x<GW;x++){
      const i=row+x;
      const iL=row+(x>0?x-1:x), iR=row+(x<GW-1?x+1:x), iU=rowU+x, iD=rowD+x;
      const lap=cu[iL]+cu[iR]+cu[iU]+cu[iD]-4*cu[i];
      let un=(2*cu[i]-pu[i]+c2*lap)*damp*bf[i];
      if(un>3)un=3; else if(un<-3)un=-3;
      pu[i]=un;
    }
  }
  const tmp=cu; cu=pu; pu=tmp;
  // drive the vibrating dippers on the fresh buffer -> radiate continuous ring trains
  for(let i=0;i<nS;i++){
    const sxc=Math.floor(SX[i]*GW), syc=Math.floor(SY[i]*GH);
    for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
      const xx=sxc+dx, yy=syc+dy; if(xx<0||yy<0||xx>=GW||yy>=GH)continue;
      cu[yy*GW+xx]=SV[i];
    }
  }
}
S.u=cu; S.up=pu;

// ---- drops: baseline K.t cadence (audio-free motion floor) + bass splashes ----
const dropIvl=(act==='storm')?0.35:(0.9-dens*0.45);
const tick=Math.floor(K.t/Math.max(0.15,dropIvl));
if(S.dTick==null||tick<S.dTick)S.dTick=tick-1;
let doDrop=false, dropAmp=0;
if(tick>S.dTick){ S.dTick=tick; doDrop=true; dropAmp=1.0; }
if(A.bass>0.35 && (K.beat|0)!==(S.bBeat|0)){ S.bBeat=K.beat|0; doDrop=true; dropAmp=Math.max(dropAmp,0.7+A.bass*0.8); }
if(doDrop){
  const dn=(act==='storm')?2:1;
  for(let q=0;q<dn;q++){
    const sk=tick*3+q*7+(P.seed|0);
    const rx=0.12+hsh(sk+1)*0.76, ry=0.12+hsh(sk+2)*0.76;
    const cx=Math.floor((rx*0.7+P.x*0.3)*GW), cy=Math.floor((ry*0.7+P.y*0.3)*GH);
    const rr=2+Math.floor(dens*3), aa=dropAmp*(hsh(sk+3)<0.5?-1:1);
    const cu2=S.u;
    for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
      const xx=cx+dx,yy=cy+dy; if(xx<0||yy<0||xx>=GW||yy>=GH)continue;
      const dd=dx*dx+dy*dy; if(dd>rr*rr)continue;
      cu2[yy*GW+xx]+=aa*Math.exp(-dd/(rr*rr*0.5));
    }
  }
}

// ---- map wave height -> color into the coarse buffer ----
const fld=S.u;
const dispGain=0.6+en*1.7+K.intensity*0.3;
const caustGain=0.4+en*1.8;
const densRich=dens;
const isCaustic=style==='caustic', isTherm=style==='thermal', isPhos=style==='phosphor', isBlue=style==='blueprint', isMerc=style==='mercury';
const buf=S.buf; buf.loadPixels(); const px=buf.pixels;
for(let y=0;y<GH;y++){
  const row=y*GW, rowU=(y>0?y-1:y)*GW, rowD=(y<GH-1?y+1:y)*GW;
  for(let x=0;x<GW;x++){
    const i=row+x;
    const iL=row+(x>0?x-1:x), iR=row+(x<GW-1?x+1:x);
    const h=fld[i];
    const gx=fld[iR]-fld[iL], gy=fld[rowD+x]-fld[rowU+x];
    const gm=Math.sqrt(gx*gx+gy*gy);
    let hn=h*dispGain; if(hn>1)hn=1; else if(hn<-1)hn=-1;
    const t=0.5+0.5*hn;
    let li=t*127|0; if(li<0)li=0; else if(li>127)li=127;
    let r=R[li],g=G[li],b=Bc[li];
    if(isCaustic){
      let hl=gm*(5+caustGain*7); if(hl>1)hl=1; hl*=hl;
      const crest=t>0.62?(t-0.62)*2.6:0; const sp=crest*crest*caustGain;
      const add=(hl*118+sp*58)*(0.55+0.45*densRich);
      r+=add*0.75; g+=add*1.0; b+=add*1.02;
    } else if(isTherm){
      let e=gm*caustGain*7; if(e>1)e=1;
      r+=e*22; g+=e*14; b+=e*4;
    } else if(isPhos){
      const q=t*nb; let d=q-Math.round(q); if(d<0)d=-d;
      const lw=0.16; let ln=d<lw?1-d/lw:0; ln*=ln;
      const glow=ln*(0.55+caustGain*0.5)*(0.6+gm*10);
      r+=glow*36; g+=glow*225; b+=glow*95;
    } else if(isBlue){
      const q=t*nb; let d=q-Math.round(q); if(d<0)d=-d;
      const lw=0.14; let ln=d<lw?1-d/lw:0; ln=Math.pow(ln,1.3);
      const glow=ln*(0.55+caustGain*0.4)*(0.6+gm*8);
      r+=glow*110; g+=glow*205; b+=glow*230;
    } else { // mercury
      let e=gm*(6+caustGain*8); if(e>1)e=1; e*=e;
      const chrome=e*150;
      r+=chrome*0.94; g+=chrome*1.0; b+=chrome*1.06;
    }
    if(r<0)r=0;else if(r>255)r=255;
    if(g<0)g=0;else if(g>255)g=255;
    if(b<0)b=0;else if(b>255)b=255;
    const o=i*4; px[o]=r; px[o+1]=g; px[o+2]=b; px[o+3]=255;
  }
}
buf.updatePixels();

// ---- composite full-bleed ----
push();
drawingContext.imageSmoothingEnabled = !(isBlue||isPhos);
if(P.alpha<100) tint(0,0,100,clp(P.alpha,0,100));
image(buf,0,0,width,height);
pop();
drawingContext.imageSmoothingEnabled = true;

// ---- faint audio shimmer on top (partial, never full-frame -> won't strobe) ----
if(A.treble>0.02||A.rms>0.02){
  push(); blendMode(ADD); noStroke();
  const gl=(A.treble*0.5+A.rms*0.4)*(0.4+en*0.6);
  fill((hb+40)%360,30,100,clp(gl*20,0,18));
  rect(0,0,width,height);
  blendMode(BLEND); pop();
}
blendMode(BLEND); drawingContext.shadowBlur=0;
